def test_r3_column_count_follows_len_b():
    a = [1, 2, 3]
    for n in (1, 2, 3, 4, 5):
        ax = task_func(a, list(range(n)))
        # one bar per (row, column) pair
        assert len(ax.patches) == len(a) * n

def test_r1_returns_axes_object():
    ax = task_func(["x", "y", "z"], [1, 2])
    assert isinstance(ax, matplotlib.axes.Axes)

def test_r2_axes_is_attached_to_current_figure():
    ax = task_func(["x", "y", "z"], [1, 2])
    assert ax in plt.gcf().axes

def _legend_labels(ax):
    legend = ax.get_legend()
    if legend is None:
        return []
    return [t.get_text() for t in legend.get_texts()]

def test_r6_columns_use_predefined_names():
    ax = task_func(["x", "y"], [1, 2, 3])
    assert _legend_labels(ax) == COLUMNS[:3]

