def test_r3_column_count_matches_len_b():
    for n in (1, 2, 3, 4, 5):
        plt.close("all")
        ax = task_func(["r1", "r2"], list(range(n)))
        assert len(ax.containers) == n

def _bar_heights(ax):
    return [p.get_height() for p in ax.patches]

def test_r5_values_are_random_not_constant():
    ax = task_func(["r1", "r2", "r3", "r4"], [1, 2, 3])
    heights = _bar_heights(ax)
    assert len(set(heights)) > 1

def _bar_heights(ax):
    return [p.get_height() for p in ax.patches]

def test_r6_values_within_unit_interval():
    ax = task_func(["r1", "r2", "r3", "r4", "r5"], [1, 2, 3, 4, 5])
    heights = _bar_heights(ax)
    assert all(0.0 <= h < 1.0 for h in heights)
